-- 1. Enable btree_gist extension to allow scalar + range operator combinations
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- 2. Create table with exclusion constraint
CREATE TABLE meeting_room_reservations (
    id SERIAL PRIMARY KEY,
    room_id INT NOT NULL,
    booking_slot TSTZRANGE NOT NULL,
    -- Room IDs must be equal (=) AND booking slots must NOT overlap (&&)
    EXCLUDE USING gist (
        room_id WITH =,
        booking_slot WITH &&
    )
);
